import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import {} from '@/primitives';
import {} from '@/text';
import {} from 'three/tsl';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Root container (adapter will set position/rotation/scale)
  const root = new Group();

  // Plane geometry and material
  const geometry = new PlaneGeometry(1, 1);
  const material = new MeshBasicNodeMaterial({ transparent: true });
  const plane = new Mesh(geometry, material);
  root.add(plane);

  // Load texture asynchronously – apply when ready
  let loadedTexture = null;
  const texturePromise = ctx.textureLoader
    .loadTexture(config.imageUrl)
    .then((tex) => {
      loadedTexture = tex;
      material.map = tex;
      material.needsUpdate = true;
    })
    .catch(() => {
      // silence loading errors; keep plane untextured
    });

  // Create text objects from config
  const items =
    config.textContent ??
    config.intent?.visualSpec?.textContent ??
    [];
  for (const item of items) {
    const textObj = ctx.fontAtlas.createText(item.text ?? '', {
      fontSize: item.typography?.fontSize ?? 39,
      color:
        (config.visual?.colors?.paper ??
          config.colors?.paper ??
          '#e8ecf2') ?? '#e8ecf2',
      align: 'center',
    });
    // Slightly in front of the plane
    textObj.position.set(0, 0, 0.01);
    root.add(textObj);
  }

  // Empty handlers container (no interactions specified)
  root.userData.handlers = {};

  // Cleanup routine
  root.userData.cleanup = () => {
    // Dispose geometry and material
    geometry.dispose();
    material.dispose();

    // Dispose loaded texture if present
    if (loadedTexture) {
      loadedTexture.dispose();
    }

    // Kill any GSAP timelines (none created here, but future safety)
    gsap.globalTimeline.clear();
  };

  // Prevent unhandled promise rejection warnings
  texturePromise.catch(() => {});

  return root;
}
